import { cx } from '@/lib/cx.js';
import styles from './Segmented.module.css';

export interface SegmentedOption<T extends string> {
  value: T;
  label: string;
}

interface SegmentedProps<T extends string> {
  label: string;
  value: T;
  options: readonly SegmentedOption<T>[];
  /** Fills the width of its container. */
  block?: boolean;
  onChange: (value: T) => void;
}

/**
 * A one-of-many switch, as the prototype's theme and strictness rows use.
 * It is a radio group rather than a row of buttons, so a keyboard and a
 * screen reader see one control with a current value.
 */
export function Segmented<T extends string>({
  label,
  value,
  options,
  block = false,
  onChange,
}: SegmentedProps<T>): React.JSX.Element {
  return (
    <div className={cx(styles.group, block && styles.block)} role="radiogroup" aria-label={label}>
      {options.map((option) => (
        <button
          key={option.value}
          type="button"
          role="radio"
          aria-checked={option.value === value}
          className={cx(styles.option, option.value === value && styles.selected)}
          onClick={() => {
            onChange(option.value);
          }}
        >
          {option.label}
        </button>
      ))}
    </div>
  );
}
